/*
	VIOC_front_line.sqf - agregado por tools/vio_build.py (copia configurada, no es del autor de la mision).
	Parche "front_line" (2026-10-18). Se compila en todas las maquinas desde init.sqf (marcadores y avisos en el cliente);
	la clasificacion corre solo en el servidor (en la partida LAN el anfitrion es el servidor y la consola LOCAL EXEC llega aqui).
	Sirve para las misiones A y B y para cualquier mapa (los datos salen del terreno en el juego).

	Problema: "demasiada IA en el mapa". Si entre los pueblos A, B y C, A y B son de un bando y C del enemigo, A ya no tiene
	que ser atacado ni capturado por la IA enemiga ni tener IA de guarnicion: se puede usar para reaparecer y comprar, pero
	el foco es B. Lo mismo para la capital y los aerodromos.

	Parametros de lobby:
	  VIOC_FRONTLINE          0 = no, 1 = si (por defecto): retaguardia protegida.
	  VIOC_FRONTLINE_RANGE    2500 (por defecto: solo los vecinos inmediatos, el ejemplo A-B-C) / 3500 / 5000 m: distancia de frente.
	  VIOC_FRONTLINE_MARKERS  0 = no, 1 = si (por defecto): aro "FRENTE" en el mapa en los pueblos de frente de tu bando.

	1) CLASIFICACION (servidor; cada VIOC_FL_PERIOD s y en cuanto un pueblo cambia de duenio; solo pueblos del Oeste o del Este;
	   los de la guerrilla no se clasifican: la milicia no ataca):
	   - FRENTE: hay un pueblo de otro duenio (el enemigo o la guerrilla) a menos de VIOC_FRONTLINE_RANGE m y alcanzable por
	     tierra (en linea recta no mas de VIOC_FL_WATER_GAP m de agua seguida; un punto en el agua sobre un camino cuenta como
	     tierra; o un camino de dos tramos secos por un puente de hasta VIOC_FL_BRIDGE_PATH x la distancia), o hay un HQ, una
	     estructura de base o un FOB enemigos vivos a menos de esa distancia.
	   - RETAGUARDIA: todo lo demas, despues de VIOC_FL_HYST s seguidos sin cumplir la condicion de frente (histeresis; al
	     cambiar de duenio el pueblo empieza como frente). Volver a frente es inmediato.
	   - Regla de seguridad: si un bando con pueblos se queda sin ningun pueblo de frente (islas, frente lejano), sus
	     VIOC_FL_SAFE_N pueblos mas cercanos a los pueblos o la base del enemigo cuentan como frente (la guerra no se congela).
	   - Union de componentes (al empezar): cada grupo de pueblos sin enlace con el resto se une a su pueblo de fuera mas cercano
	     (por tierra hasta VIOC_FL_JOIN_MAX x la distancia, por un puente o, sin ningun puente hallado, en linea recta a la
	     distancia de frente). Lo que queda suelto (islas sin paso) y los pueblos sin ningun vecino son siempre frente.
	   - Bajo ataque: un pueblo de frente con enemigos a VIOC_FL_GAR_ENEMY m (o grupos vivos de la ofensiva de la mision B
	     contra el) no pasa a retaguardia.
	   - Distancias y paso por tierra se calculan UNA vez al empezar (pares a menos de la distancia de frente; puentes: tramos
	     de camino de nearRoads sobre el agua, cerca de los pares sin paso en linea recta). Cada recalculo solo lee duenios,
	     HQ y estructuras. Nada por frame.
	   - Se publica en cada pueblo (setVariable publico, solo cuando cambia): vioc_fl_rear (true = retaguardia) y vioc_fl_sid
	     (duenio con el que se clasifico). VIOC_FL_fnc_isRear [pueblo] -> true si es retaguardia de su duenio de hoy.
	2) EFECTOS en un pueblo de retaguardia (ganchos en archivos ajenos, todos con !isNil "VIOC_FL_fnc_..." y el parametro):
	   - Captura (town_capture.fsm y town_camp.fsm): la presencia de IA que no es del duenio no cuenta (no baja el SV, no da
	     el aviso de ataque, no cambia los campamentos). Cuentan los jugadores, la gente de los grupos que manda un jugador,
	     los soldados de las operaciones especiales que pidio un jugador (vioc_so_preq) y las escuadras que un comandante
	     jugador mando a ESE pueblo (VIOC_FL_fnc_cmdOrder).
	   - Objetivos de la IA: escuadras IA de BECTI (Functions_FSM_UpdateAI.sqf: eleccion del pueblo y cambio de objetivo en
	     camino; si no queda ningun pueblo enemigo de frente, la eleccion original), defensores del comandante IA
	     (Functions_FSM_UpdateCommander.sqf: solo pueblos propios de frente), contraataques, pinzas y maniobras de ai_tactics,
	     operaciones especiales (VIOC_specops.sqf: objetivo, avance al pueblo siguiente y refuerzo de pueblos propios atacados),
	     asalto aereo (VIOC_air_assault.sqf), refuerzos y ataque prioritario de la
	     capital (VIOC_capital_reinforce.sqf), durmientes, IED y coche bomba (VIOC_irregular.sqf: solo cerca de pueblos que
	     no son retaguardia, a menos de VIOC_FL_IW_R m) y, en la mision B (parche front_line_mb), la guarnicion presente de
	     los pueblos clave (keyTick) y la ofensiva inicial.
	   - Sin IA de guarnicion: si un pueblo de retaguardia tiene la guarnicion de BECTI activa sin enemigos a VIOC_FL_GAR_ENEMY m
	     ni jugadores a VIOC_FL_GAR_FREE m, se adelanta su desactivacion (la limpieza original de town_occupation.fsm). Los
	     refuerzos de capital_reinforce que defienden una capital de retaguardia se borran con las mismas condiciones.
	   - El jugador puede atacar y capturar cualquier pueblo; reaparecer y comprar en la retaguardia no cambia.
	3) JUGADOR: aro naranja "FRENTE" (marcadores locales) en los pueblos de frente de su bando y avisos cortos:
	   "[Frente] X queda en la retaguardia: ya no puede ser atacado." / "[Frente] X vuelve a ser frente: ...".

	Consola (LOCAL EXEC en el anfitrion; en un servidor dedicado, SERVER EXEC):
	  hint (call VIOC_FL_fnc_info);                     estado: cada pueblo, frente o retaguardia y por que (portapapeles)
	  hint ([] call VIOC_FL_fnc_why);                   el pueblo mas cercano a ti: vecinos, distancias, agua, puentes, bases
	  hint (call VIOC_FL_fnc_targets);                  pueblo al que va cada escuadra IA de BECTI (avisa si alguno es retaguardia enemiga)
	  hint ([] call VIOC_FL_fnc_recalc);                recalcular YA (con histeresis);  hint ([true] call VIOC_FL_fnc_recalc);  sin histeresis
	  hint ([call VIOC_FL_fnc_nearTown, "rear"] call VIOC_FL_fnc_force);   forzar retaguardia ("front" = forzar frente, "" = quitar)
	  call VIOC_FL_fnc_markers;                         marcadores locales de todos los pueblos (frente/retaguardia, los dos bandos)
	  VIOC_FL_DEBUG = true;                             cada cambio en el chat del anfitrion
	  VIOC_FL_INFO = [recalculos, a retaguardia, a frente, guarniciones retiradas, grupos de refuerzo borrados, regla de seguridad]
*/
if (!isNil "VIOC_FL_LOADED") exitWith {};
VIOC_FL_LOADED = true;

//--- Ajustes
VIOC_FL_PERIOD = 30;              // s entre recalculos
VIOC_FL_POLL = 5;                 // s: se mira si algun pueblo cambio de duenio (recalculo inmediato)
VIOC_FL_HYST = 60;                // s seguidos sin condicion de frente para pasar a retaguardia
VIOC_FL_WATER_GAP = 350;          // m de agua seguida en linea recta que todavia se acepta (como mission_b y ai_tactics)
VIOC_FL_STEP = 50;                // m entre muestras de la linea recta
VIOC_FL_BRIDGE_SEARCH = 400;      // m de mas alrededor de un par sin paso donde se buscan puentes
VIOC_FL_BRIDGE_JOIN = 60;         // m entre tramos de un mismo puente
VIOC_FL_BRIDGE_MIN = 50;          // m: largo minimo de un puente que cuenta
VIOC_FL_BRIDGE_PIECES = 600;      // tramos de puente como mucho (tope de la busqueda)
VIOC_FL_BRIDGE_PATH = 1.25;       // camino por un puente: como mucho esto x la distancia de frente
VIOC_FL_SAFE_N = 2;               // regla de seguridad: pueblos que pasan a frente si un bando se queda sin ninguno
VIOC_FL_JOIN_TRIES = 12;          // union de componentes: pares mas cercanos que se prueban por componente
VIOC_FL_JOIN_MAX = 2;             // union de componentes: hasta esto x la distancia de frente (por tierra)
VIOC_FL_IW_R = 1500;              // m: IED y coche bomba solo a menos de esto de un pueblo que no es retaguardia
VIOC_FL_GAR_ENEMY = 1200;         // m sin enemigos para retirar la guarnicion de un pueblo de retaguardia (y "bajo ataque")
VIOC_FL_GAR_FREE = 1200;          // m sin jugadores para retirarla (se borra fuera de su vista)
VIOC_FL_GAR_MIN = 60;             // s activa como minimo antes de adelantar la desactivacion
VIOC_FL_MK_PERIOD = 10;           // s: revision de los marcadores del cliente
VIOC_FL_MK_R = 380;               // m: radio del aro "FRENTE"
if (isNil "VIOC_FL_DEBUG") then {VIOC_FL_DEBUG = false};

//--- ---------------------------------- comun (todas las maquinas) ----------------------------------
//--- [nombre, defecto, valores validos] -> valor del lobby
VIOC_FL_fnc_par = {
	params ["_n", "_d", "_ok"];
	private _v = missionNamespace getVariable [_n, _d];
	if !((_v isEqualType 0) && {_v in _ok}) then {_v = _d};
	_v
};

//--- [pueblo] -> true si es retaguardia de su duenio de hoy (con el parametro activo y la clasificacion lista)
VIOC_FL_fnc_isRear = {
	params [["_t", objNull]];
	if (!(missionNamespace getVariable ["VIOC_FL_ACTIVE", false]) || {!(_t isEqualType objNull)} || {isNull _t}) exitWith {false};
	(_t getVariable ["vioc_fl_rear", false]) && {(_t getVariable ["vioc_fl_sid", -9]) isEqualTo (_t getVariable ["cti_town_sideID", -1])}
};

//--- [posicion] -> true si hay a menos de VIOC_FL_IW_R m un pueblo que no es retaguardia (guerrilla o frente)
VIOC_FL_fnc_nearFront = {
	params ["_p"];
	if !(missionNamespace getVariable ["VIOC_FL_ACTIVE", false]) exitWith {true};
	((missionNamespace getVariable ["CTI_Towns", []]) findIf {((_x distance2D _p) < VIOC_FL_IW_R) && {!([_x] call VIOC_FL_fnc_isRear)}}) >= 0
};

VIOC_FL_fnc_tname = {
	params ["_t"];
	if (isNull _t) exitWith {"?"};
	_t getVariable ["cti_town_name", "?"]
};

//--- [texto]: aviso corto (llega con remoteExecCall al bando duenio)
VIOC_FL_fnc_note = {
	params [["_t", ""]];
	if (hasInterface && {_t isEqualType ""} && {_t != ""}) then {systemChat _t};
};

//--- Cliente: aro naranja y texto "FRENTE" en los pueblos de frente del bando del jugador (marcadores locales)
VIOC_FL_fnc_clientLoop = {
	waitUntil {sleep 2; !isNil "CTI_P_SideID" && {!isNil "CTI_InitTowns"} && {!isNil "CTI_Towns"}};
	if ((["VIOC_FRONTLINE", 1, [0, 1]] call VIOC_FL_fnc_par) < 1) exitWith {};
	if ((["VIOC_FRONTLINE_MARKERS", 1, [0, 1]] call VIOC_FL_fnc_par) < 1) exitWith {};
	private _sig = [];
	private _made = [];
	while {!(missionNamespace getVariable ["CTI_GameOver", false])} do {
		private _now = [];
		private _sid = missionNamespace getVariable ["CTI_P_SideID", -1];
		if ((missionNamespace getVariable ["VIOC_FL_ACTIVE", false]) && {_sid in [CTI_WEST_ID, CTI_EAST_ID]}) then {
			{
				if (((_x getVariable ["cti_town_sideID", -1]) isEqualTo _sid) && {!([_x] call VIOC_FL_fnc_isRear)}) then {_now pushBack _forEachIndex};
			} forEach CTI_Towns;
		};
		if !(_now isEqualTo _sig) then {
			{
				deleteMarkerLocal format ["VIOC_FL_r%1", _x];
				deleteMarkerLocal format ["VIOC_FL_t%1", _x];
			} forEach _made;
			_made = [];
			{
				private _t = CTI_Towns select _x;
				private _p = getPosATL _t;
				private _m = createMarkerLocal [format ["VIOC_FL_r%1", _x], [_p select 0, _p select 1, 0]];
				_m setMarkerShapeLocal "ELLIPSE";
				_m setMarkerBrushLocal "Border";
				_m setMarkerColorLocal "ColorOrange";
				_m setMarkerSizeLocal [VIOC_FL_MK_R, VIOC_FL_MK_R];
				private _q = _p getPos [VIOC_FL_MK_R + 60, 0];
				private _m2 = createMarkerLocal [format ["VIOC_FL_t%1", _x], [_q select 0, _q select 1, 0]];
				_m2 setMarkerTypeLocal "EmptyIcon";
				_m2 setMarkerColorLocal "ColorOrange";
				_m2 setMarkerTextLocal "FRENTE";
				_made pushBack _x;
			} forEach _now;
			_sig = _now;
		};
		sleep VIOC_FL_MK_PERIOD;
	};
};
if (hasInterface) then {[] spawn VIOC_FL_fnc_clientLoop};

//--- ---------------------------------- servidor ----------------------------------
if (!isServer) exitWith {};

VIOC_FL_ON = 0;
VIOC_FL_R = 2500;
VIOC_FL_T = [];                   // pueblos (copia de CTI_Towns al empezar)
VIOC_FL_POS = [];                 // sus posiciones [x, y, 0]
VIOC_FL_LINKS = [];               // por pueblo: [[indice, distancia, largo por puente o 0], ...] (ordenado por distancia)
VIOC_FL_CUT = [];                 // pares a la distancia de frente sin paso por tierra: [i, j, distancia, agua seguida]
VIOC_FL_BRIDGES = [];             // puentes encontrados: [extremo, extremo, largo]
VIOC_FL_JOINS = [];               // uniones de componentes: [i, j, distancia, como]
VIOC_FL_ISO = [];                 // por pueblo: true si su componente no se pudo unir a la principal (isla sin paso: siempre frente)
VIOC_FL_ST = [];                  // por pueblo: [retaguardia, ultima vez con condicion de frente, duenio, motivo, condicion de frente ahora]
VIOC_FL_FORCE = createHashMap;    // consola: indice -> "rear" / "front"
VIOC_FL_NEXT = -1;
VIOC_FL_NOW = false;
VIOC_FL_T0 = -1;
VIOC_FL_INFO = [0, 0, 0, 0, 0, 0];

VIOC_FL_fnc_log = {
	params ["_m"];
	diag_log format ["[VIOC front_line] %1", _m];
	if (VIOC_FL_DEBUG && {hasInterface}) then {systemChat format ["[FL] %1", _m]};
};

VIOC_FL_fnc_stat = {
	params ["_i", ["_n", 1]];
	VIOC_FL_INFO set [_i, (VIOC_FL_INFO select _i) + _n];
};

VIOC_FL_fnc_sideName = {
	params ["_sid"];
	if (_sid == CTI_WEST_ID) exitWith {"Oeste"};
	if (_sid == CTI_EAST_ID) exitWith {"Este"};
	if (_sid == CTI_RESISTANCE_ID) exitWith {"guerrilla"};
	"nadie"
};

//--- Jugadores reales (sin clientes sin cabeza)
VIOC_FL_fnc_players = {
	allPlayers select {alive _x && {!(_x isKindOf "HeadlessClient_F")}}
};

//--- [unidad, pueblo] -> true si su grupo (Oeste/Este) va a ESE pueblo por una orden manual de un comandante JUGADOR
//--- (cti_order CTI_ORDER_TAKETOWN / CTI_ORDER_TAKEHOLDTOWN y cti_order_pos = el pueblo; no maniobras de ai_tactics ni de
//--- capital_reinforce): el bucle TakeTown de BECTI solo termina si el pueblo es propio, asi que tienen que poder tomarlo
VIOC_FL_fnc_cmdOrder = {
	params ["_u", "_t"];
	private _g = group _u;
	if (isNull _g || {!((side _g) in [west, east])}) exitWith {false};
	if (!isNil {_g getVariable "vioc_tac_man"} || {!isNil {_g getVariable "vioc_cr_role"}}) exitWith {false};
	if !((_g getVariable ["cti_order", -1]) in [CTI_ORDER_TAKETOWN, CTI_ORDER_TAKEHOLDTOWN]) exitWith {false};
	if !((_g getVariable ["cti_order_pos", objNull]) isEqualTo _t) exitWith {false};
	private _cg = (side _g) call CTI_CO_FNC_GetSideCommander;
	if (isNil "_cg" || {!(_cg isEqualType grpNull)} || {isNull _cg}) exitWith {false};
	isPlayer (leader _cg)
};

//--- [unidad o vehiculo, pueblo] -> true si es un jugador, alguien del grupo de un jugador, un soldado de una operacion especial
//--- pedida por un jugador (vioc_so_preq de specops_player), una escuadra mandada a ese pueblo por un comandante jugador
//--- (VIOC_FL_fnc_cmdOrder) o un vehiculo con uno de ellos dentro
VIOC_FL_fnc_human = {
	params ["_o", "_t"];
	if (_o isKindOf "CAManBase") exitWith {isPlayer _o || {isPlayer (leader (group _o))} || {_o getVariable ["vioc_so_preq", false]} || {[_o, _t] call VIOC_FL_fnc_cmdOrder}};
	((crew _o) findIf {isPlayer _x || {isPlayer (leader (group _x))} || {_x getVariable ["vioc_so_preq", false]} || {[_x, _t] call VIOC_FL_fnc_cmdOrder}}) >= 0
};

//--- [pueblo, sideID del duenio, objetos] -> objetos que cuentan para la captura (ganchos de town_capture.fsm y town_camp.fsm).
//--- En la retaguardia de su duenio solo cuentan los del duenio, los jugadores y la gente de los grupos de un jugador.
VIOC_FL_fnc_capFilter = {
	params ["_t", "_sid", "_objs"];
	if !([_t] call VIOC_FL_fnc_isRear) exitWith {_objs};
	if ((_t getVariable ["cti_town_sideID", -1]) != _sid) exitWith {_objs};
	private _own = (_sid) call CTI_CO_FNC_GetSideFromID;
	_objs select {((side _x) isEqualTo _own) || {[_x, _t] call VIOC_FL_fnc_human}}
};

//--- [centro, bando o sideID, objetivo original] -> pueblo para una escuadra IA de BECTI (ganchos de Functions_FSM_UpdateAI.sqf):
//--- el original si no es retaguardia; si lo es, el pueblo no propio mas cercano que no sea retaguardia; si no hay ninguno, el original
VIOC_FL_fnc_aiTarget = {
	params ["_c", "_side", ["_orig", objNull]];
	if (isNull _orig || {!([_orig] call VIOC_FL_fnc_isRear)}) exitWith {_orig};
	private _sid = if (_side isEqualType west) then {(_side) call CTI_CO_FNC_GetSideID} else {_side};
	private _cands = CTI_Towns select {((_x getVariable ["cti_town_sideID", -1]) != _sid) && {!([_x] call VIOC_FL_fnc_isRear)}};
	if (count _cands == 0) exitWith {_orig};
	[_c, _cands] call CTI_CO_FNC_GetClosestEntity
};

//--- [a, b] (posiciones) -> [seco, agua seguida]: muestra cada VIOC_FL_STEP m; un punto en el agua sobre un camino (puente) es tierra
VIOC_FL_fnc_dry = {
	params ["_a", "_b"];
	private _d = _a distance2D _b;
	private _n = (ceil (_d / VIOC_FL_STEP)) max 1;
	private _st = _d / _n;
	private _run = 0;
	private _worst = 0;
	for "_i" from 1 to (_n - 1) do {
		private _p = [(_a select 0) + ((_b select 0) - (_a select 0)) * _i / _n, (_a select 1) + ((_b select 1) - (_a select 1)) * _i / _n, 0];
		_run = if ((surfaceIsWater _p) && {!(isOnRoad _p)}) then {_run + _st} else {0};
		_worst = _worst max _run;
		if (_run > VIOC_FL_WATER_GAP) exitWith {};
	};
	[_worst <= VIOC_FL_WATER_GAP, _worst]
};

//--- [pares sin paso [[i, j, d, agua], ...]] -> puentes [[extremo, extremo, largo], ...]: tramos de camino (nearRoads) sobre el agua
//--- cerca de esos pares, unidos en cadenas (tramos a menos de VIOC_FL_BRIDGE_JOIN m); extremos = los dos tramos mas alejados
VIOC_FL_fnc_bridges = {
	params ["_fail"];
	private _pieces = [];
	private _seen = createHashMap;
	{
		_x params ["_i", "_j", "_d"];
		private _a = VIOC_FL_POS select _i;
		private _b = VIOC_FL_POS select _j;
		private _mid = [((_a select 0) + (_b select 0)) / 2, ((_a select 1) + (_b select 1)) / 2, 0];
		if ((count _pieces) < VIOC_FL_BRIDGE_PIECES) then {
			{
				private _q = getPosATL _x;
				private _k = format ["%1_%2", round (_q select 0), round (_q select 1)];
				if (!(_k in _seen) && {(count _pieces) < VIOC_FL_BRIDGE_PIECES}) then {
					_seen set [_k, true];
					_pieces pushBack [_q select 0, _q select 1, 0];
				};
			} forEach ((_mid nearRoads (((_d / 2) + VIOC_FL_BRIDGE_SEARCH) min 3000)) select {surfaceIsWater (getPosATL _x)});
		};
		sleep 0.02;
	} forEach _fail;
	private _res = [];
	private _used = _pieces apply {false};
	for "_i" from 0 to ((count _pieces) - 1) do {
		if !(_used select _i) then {
			_used set [_i, true];
			private _c = [_pieces select _i];
			private _k = 0;
			while {_k < count _c} do {
				private _p = _c select _k;
				{
					if (!(_used select _forEachIndex) && {(_x distance2D _p) < VIOC_FL_BRIDGE_JOIN}) then {_used set [_forEachIndex, true]; _c pushBack _x};
				} forEach _pieces;
				_k = _k + 1;
			};
			private _best = [0, _c select 0, _c select 0];
			{
				private _e = _x;
				{
					private _dd = _e distance2D _x;
					if (_dd > (_best select 0)) then {_best = [_dd, _e, _x]};
				} forEach _c;
			} forEach _c;
			if ((_best select 0) >= VIOC_FL_BRIDGE_MIN) then {_res pushBack [_best select 1, _best select 2, _best select 0]};
		};
	};
	_res
};

//--- [a, b, puentes] -> largo del camino mas corto a -> extremo -> (puente) -> extremo -> b con los dos tramos secos, o -1
VIOC_FL_fnc_viaBridge = {
	params ["_a", "_b", "_br"];
	private _best = -1;
	{
		_x params ["_e1", "_e2", "_len"];
		{
			_x params ["_p", "_q"];
			private _tot = (_a distance2D _p) + _len + (_q distance2D _b);
			if ((_tot <= (VIOC_FL_BRIDGE_PATH * VIOC_FL_R)) && {(_best < 0) || {_tot < _best}}) then {
				if ((([_a, _p] call VIOC_FL_fnc_dry) select 0) && {([_q, _b] call VIOC_FL_fnc_dry) select 0}) then {_best = _tot};
			};
		} forEach [[_e1, _e2], [_e2, _e1]];
	} forEach _br;
	_best
};

//--- -> [componente de cada pueblo, [[indices], ...]]: componentes del grafo VIOC_FL_LINKS (BFS)
VIOC_FL_fnc_comps = {
	private _n = count VIOC_FL_T;
	private _id = VIOC_FL_T apply {-1};
	private _list = [];
	for "_i" from 0 to (_n - 1) do {
		if ((_id select _i) < 0) then {
			private _c = count _list;
			private _mem = [_i];
			_id set [_i, _c];
			private _k = 0;
			while {_k < count _mem} do {
				{
					private _j = _x select 0;
					if ((_id select _j) < 0) then {_id set [_j, _c]; _mem pushBack _j};
				} forEach (VIOC_FL_LINKS select (_mem select _k));
				_k = _k + 1;
			};
			_list pushBack _mem;
		};
	};
	[_id, _list]
};

//--- -> nombres de los pueblos aislados (VIOC_FL_ISO)
VIOC_FL_fnc_isoNames = {
	private _r = [];
	{ if (VIOC_FL_ISO param [_forEachIndex, false]) then {_r pushBack ([_x] call VIOC_FL_fnc_tname)} } forEach VIOC_FL_T;
	_r
};

//--- Une cada componente del grafo (de la mas chica a la mas grande) a su pueblo de fuera mas cercano que se pueda, entre los
//--- VIOC_FL_JOIN_TRIES pares mas cercanos y a menos de VIOC_FL_JOIN_MAX x la distancia de frente: por tierra (linea recta seca),
//--- por un puente (VIOC_FL_fnc_viaBridge, camino <= VIOC_FL_BRIDGE_PATH x la distancia) o, si no se hallo NINGUN puente en el
//--- mapa, en linea recta a la distancia de frente (ultimo recurso). Tanoa con 2500 m: Lijnhaven y Port-Boise se unen a Harcourt
//--- (2506 m por tierra). Las componentes que quedan sueltas (islas sin paso) son VIOC_FL_ISO: siempre frente, como el original.
VIOC_FL_fnc_join = {
	VIOC_FL_JOINS = [];
	private _failed = [];
	private _guard = 0;
	private _go = true;
	while {_go && {_guard < (count VIOC_FL_T)}} do {
		_guard = _guard + 1;
		_go = false;
		(call VIOC_FL_fnc_comps) params ["_id", "_list"];
		if (count _list > 1) then {
			private _ord = _list apply {[count _x, _x]};
			_ord sort true;
			{
				private _mem = _x select 1;
				if (!_go && {(_failed findIf {_x isEqualTo _mem}) < 0}) then {
					private _cands = [];
					{
						private _i = _x;
						private _pi = VIOC_FL_POS select _i;
						{ if ((_id select _forEachIndex) != (_id select _i)) then {_cands pushBack [_pi distance2D _x, _i, _forEachIndex]} } forEach VIOC_FL_POS;
					} forEach _mem;
					_cands sort true;
					private _done = false;
					{
						_x params ["_d", "_i", "_j"];
						if (!_done && {_forEachIndex < VIOC_FL_JOIN_TRIES} && {_d <= (VIOC_FL_JOIN_MAX * VIOC_FL_R)}) then {
							private _a = VIOC_FL_POS select _i;
							private _b = VIOC_FL_POS select _j;
							private _kind = "";
							private _via = 0;
							if (([_a, _b] call VIOC_FL_fnc_dry) select 0) then {_kind = "tierra"} else {
								if (count VIOC_FL_BRIDGES > 0) then {
									_via = [_a, _b, VIOC_FL_BRIDGES] call VIOC_FL_fnc_viaBridge;
									if (_via > 0) then {_kind = "puente"} else {_via = 0};
								} else {
									if (_d <= VIOC_FL_R) then {_kind = "linea recta (no se hallo ningun puente)"};
								};
							};
							if (_kind != "") then {
								(VIOC_FL_LINKS select _i) pushBack [_j, _d, _via];
								(VIOC_FL_LINKS select _j) pushBack [_i, _d, _via];
								VIOC_FL_JOINS pushBack [_i, _j, _d, _kind];
								_done = true;
							};
						};
					} forEach _cands;
					if (_done) then {_go = true} else {_failed pushBack _mem};
				};
			} forEach _ord;
		};
		sleep 0.01;
	};
	(call VIOC_FL_fnc_comps) params ["", "_list2"];
	private _big = 0;
	{ if ((count _x) > (count (_list2 select _big))) then {_big = _forEachIndex} } forEach _list2;
	VIOC_FL_ISO = VIOC_FL_T apply {false};
	{
		if (_forEachIndex != _big) then { { VIOC_FL_ISO set [_x, true] } forEach _x };
	} forEach _list2;
	[format ["componentes: %1 al final; uniones %2; aislados (siempre frente): %3", count _list2,
		VIOC_FL_JOINS apply {format ["%1-%2 %3 m (%4)", [VIOC_FL_T select (_x select 0)] call VIOC_FL_fnc_tname, [VIOC_FL_T select (_x select 1)] call VIOC_FL_fnc_tname,
		round (_x select 2), _x select 3]}, call VIOC_FL_fnc_isoNames]] call VIOC_FL_fnc_log;
};

//--- Una vez al empezar (programado, con pausas): pares a la distancia de frente, paso por tierra y puentes
VIOC_FL_fnc_prep = {
	VIOC_FL_T = +CTI_Towns;
	VIOC_FL_POS = VIOC_FL_T apply {private _q = getPosATL _x; [_q select 0, _q select 1, 0]};
	private _n = count VIOC_FL_T;
	VIOC_FL_LINKS = [];
	for "_i" from 1 to _n do {VIOC_FL_LINKS pushBack []};
	VIOC_FL_CUT = [];
	private _fail = [];
	for "_i" from 0 to (_n - 2) do {
		for "_j" from (_i + 1) to (_n - 1) do {
			private _d = (VIOC_FL_POS select _i) distance2D (VIOC_FL_POS select _j);
			if (_d <= VIOC_FL_R) then {
				([VIOC_FL_POS select _i, VIOC_FL_POS select _j] call VIOC_FL_fnc_dry) params ["_ok", "_w"];
				if (_ok) then {
					(VIOC_FL_LINKS select _i) pushBack [_j, _d, 0];
					(VIOC_FL_LINKS select _j) pushBack [_i, _d, 0];
				} else {
					_fail pushBack [_i, _j, _d, _w];
				};
			};
		};
		sleep 0.01;
	};
	VIOC_FL_BRIDGES = if (count _fail > 0) then {[_fail] call VIOC_FL_fnc_bridges} else {[]};
	{
		_x params ["_i", "_j", "_d", "_w"];
		private _via = if (count VIOC_FL_BRIDGES > 0) then {[VIOC_FL_POS select _i, VIOC_FL_POS select _j, VIOC_FL_BRIDGES] call VIOC_FL_fnc_viaBridge} else {-1};
		if (_via > 0) then {
			(VIOC_FL_LINKS select _i) pushBack [_j, _d, _via];
			(VIOC_FL_LINKS select _j) pushBack [_i, _d, _via];
		} else {
			VIOC_FL_CUT pushBack _x;
		};
		sleep 0.01;
	} forEach _fail;
	call VIOC_FL_fnc_join; //--- revision adversarial (ALTO-1): sin componentes sueltas por un par a pocos metros de la distancia de frente
	{
		private _l = _x apply {[_x select 1, _x select 0, _x]};
		_l sort true;
		VIOC_FL_LINKS set [_forEachIndex, _l apply {_x select 2}];
	} forEach VIOC_FL_LINKS;
	private _nl = 0;
	private _nb = 0;
	{
		_nl = _nl + count _x;
		_nb = _nb + ({(_x select 2) > 0} count _x);
	} forEach VIOC_FL_LINKS;
	[format ["%1 pueblos, distancia de frente %2 m: %3 pares unidos por tierra (%4 por un puente), %5 pares sin paso; %6 puentes: %7",
		_n, VIOC_FL_R, round (_nl / 2), round (_nb / 2), count VIOC_FL_CUT, count VIOC_FL_BRIDGES,
		VIOC_FL_BRIDGES apply {[round ((_x select 0) select 0), round ((_x select 0) select 1), round (_x select 2)]}]] call VIOC_FL_fnc_log;
};

//--- [bando] -> [[posicion, tipo], ...]: HQ vivo, estructuras vivas y FOB del bando
