//--- [sin histeresis, primera vez]: clasifica todos los pueblos y publica lo que cambio (se llama dentro de isNil: atomico)
VIOC_FL_fnc_classify = {
	params [["_now", false], ["_first", false]];
	private _n = count VIOC_FL_T;
	if (_n == 0) exitWith {};
	private _own = VIOC_FL_T apply {_x getVariable ["cti_town_sideID", -1]};
	private _as = [[west] call VIOC_FL_fnc_assets, [east] call VIOC_FL_fnc_assets];
	//--- condicion de frente
	private _cond = [];
	for "_i" from 0 to (_n - 1) do {
		private _s = _own select _i;
		private _res = [false, ""];
		if (_s in [CTI_WEST_ID, CTI_EAST_ID]) then {
			private _l = VIOC_FL_LINKS select _i;
			private _k = _l findIf {(_own select (_x select 0)) != _s};
			if (_k >= 0) then {
				(_l select _k) params ["_j", "_d", "_via"];
				_res = [true, format ["%1 (%2) a %3 m%4", [VIOC_FL_T select _j] call VIOC_FL_fnc_tname, [_own select _j] call VIOC_FL_fnc_sideName, round _d,
					["", format [" (por un puente, camino de %1 m)", round _via]] select (_via > 0)]];
			} else {
				private _ea = _as select ([1, 0] select (_s == CTI_EAST_ID));
				private _tp = VIOC_FL_POS select _i;
				private _m = _ea findIf {((_x select 0) distance2D _tp) <= VIOC_FL_R};
				if (_m >= 0) then {_res = [true, format ["%1 enemigo a %2 m", (_ea select _m) select 1, round (((_ea select _m) select 0) distance2D _tp)]]};
			};
			//--- revision adversarial (MEDIO-1): sin ningun vecino por tierra o en una isla sin paso: siempre frente, como el original
			if (!(_res select 0) && {(count _l == 0) || {VIOC_FL_ISO param [_i, false]}}) then {_res = [true, "aislado (isla sin paso por tierra a otros pueblos): siempre frente, como el original"]};
		};
		_cond pushBack _res;
	};
	//--- regla de seguridad: un bando con pueblos y sin ningun pueblo de frente
	{
		private _s = _x;
		private _mine = [];
		for "_i" from 0 to (_n - 1) do {if ((_own select _i) == _s) then {_mine pushBack _i}};
		if ((count _mine > 0) && {(_mine findIf {(_cond select _x) select 0}) < 0}) then {
			private _en = [CTI_EAST_ID, CTI_WEST_ID] select (_s == CTI_EAST_ID);
			private _tgt = (_as select ([1, 0] select (_s == CTI_EAST_ID))) apply {_x select 0};
			for "_i" from 0 to (_n - 1) do {if ((_own select _i) == _en) then {_tgt pushBack (VIOC_FL_POS select _i)}};
			if (count _tgt > 0) then {
				private _keys = _mine apply {
					private _tp = VIOC_FL_POS select _x;
					[selectMin (_tgt apply {_x distance2D _tp}), _x]
				};
				_keys sort true;
				{ _cond set [_x select 1, [true, "regla de seguridad: el bando no tenia ningun pueblo de frente (de los mas cercanos al enemigo)"]] } forEach (_keys select [0, VIOC_FL_SAFE_N]);
				[5] call VIOC_FL_fnc_stat;
			};
		};
	} forEach [CTI_WEST_ID, CTI_EAST_ID];
	//--- histeresis, forzados de consola y publicacion
	private _toRear = [[], []];
	private _toFront = [[], []];
	for "_i" from 0 to (_n - 1) do {
		private _t = VIOC_FL_T select _i;
		private _s = _own select _i;
		(VIOC_FL_ST select _i) params ["_rear", "_last", "_sid0"];
		(_cond select _i) params ["_fr", "_why"];
		private _f = VIOC_FL_FORCE getOrDefault [_i, ""];
		private _nr = false;
		if (_s in [CTI_WEST_ID, CTI_EAST_ID]) then {
			if (_f == "front") then {_fr = true; _why = "forzado desde la consola"};
			if (_f == "rear") then {_fr = false};
			//--- revision adversarial (ALTO-3): un pueblo de frente bajo ataque no pasa a retaguardia (enemigos a VIOC_FL_GAR_ENEMY m o
			//--- grupos vivos de la ofensiva de la mision B contra el); solo frena el paso de frente a retaguardia
			if (!_fr && {!_rear} && {_f == ""} && {_sid0 == _s}) then {
				private _en = [(_t nearEntities ["AllVehicles", VIOC_FL_GAR_ENEMY]) unitsBelowHeight 40, (_s) call CTI_CO_FNC_GetSideFromID] call CTI_CO_FNC_GetAreaEnemiesCount;
				private _wv = missionNamespace getVariable ["VIOC_MB_WAVES", []];
				if !(_wv isEqualType []) then {_wv = []};
				private _mb = (_wv findIf {(_x isEqualType []) && {count _x > 3} && {(_x select 3) isEqualTo _t} && {(_x select 0) isEqualType grpNull} && {!isNull (_x select 0)}
					&& {({alive _x} count (units (_x select 0))) > 0}}) >= 0;
				if ((_en > 0) || {_mb}) then {_fr = true; _why = format ["bajo ataque (%1)", ["ofensiva de la mision B", format ["%1 enemigos a %2 m", _en, VIOC_FL_GAR_ENEMY]] select (_en > 0)]};
			};
			if (_fr) then {
				_last = time;
			} else {
				if (_sid0 != _s) then {_last = time}; //--- recien tomado: la espera empieza ahora
				_nr = _now || {_f == "rear"} || {(time - _last) >= VIOC_FL_HYST};
				if (_f == "rear") then {_why = "forzado desde la consola"};
			};
		} else {
			_last = time;
			_why = "";
		};
		if (!(_nr isEqualTo _rear) || {_sid0 != _s}) then {
			_t setVariable ["vioc_fl_rear", _nr, true];
			_t setVariable ["vioc_fl_sid", _s, true];
			if (!_first && {_sid0 == _s} && {_s in [CTI_WEST_ID, CTI_EAST_ID]}) then {
				private _k = [0, 1] select (_s == CTI_EAST_ID);
				if (_nr) then {(_toRear select _k) pushBack _i; [1] call VIOC_FL_fnc_stat} else {(_toFront select _k) pushBack _i; [2] call VIOC_FL_fnc_stat};
				[format ["%1 (%2): %3 (%4)", [_t] call VIOC_FL_fnc_tname, [_s] call VIOC_FL_fnc_sideName, ["vuelve a ser FRENTE", "pasa a RETAGUARDIA"] select _nr,
					[_why, "sin pueblos de otro duenio ni bases enemigas a la distancia de frente"] select _nr]] call VIOC_FL_fnc_log;
			};
		};
		VIOC_FL_ST set [_i, [_nr, _last, _s, _why, _fr]];
	};
	//--- avisos cortos al bando duenio
	{
		private _side = _x;
		private _tr = _toRear select _forEachIndex;
		private _tf = _toFront select _forEachIndex;
		if (count _tr > 0) then {
			private _nm = (_tr apply {[VIOC_FL_T select _x] call VIOC_FL_fnc_tname}) joinString ", ";
			private _txt = if (count _tr == 1) then {format ["[Frente] %1 queda en la retaguardia: ya no puede ser atacado.", _nm]} else {
				format ["[Frente] %1 quedan en la retaguardia: ya no pueden ser atacados.", _nm]};
			[_txt] remoteExecCall ["VIOC_FL_fnc_note", _side];
		};
		if (count _tf > 0) then {
			private _nm = (_tf apply {[VIOC_FL_T select _x] call VIOC_FL_fnc_tname}) joinString ", ";
			private _txt = if (count _tf == 1) then {format ["[Frente] %1 vuelve a ser frente: la IA enemiga puede atacarlo.", _nm]} else {
				format ["[Frente] %1 vuelven a ser frente: la IA enemiga puede atacarlos.", _nm]};
			[_txt] remoteExecCall ["VIOC_FL_fnc_note", _side];
		};
	} forEach [west, east];
	[0] call VIOC_FL_fnc_stat;
	VIOC_FL_NEXT = time + VIOC_FL_PERIOD;
};

//--- Guarniciones de BECTI activas en pueblos de retaguardia sin enemigos a VIOC_FL_GAR_ENEMY m ni jugadores a VIOC_FL_GAR_FREE m:
