			private _sid = _t getVariable ["cti_town_sideID", -1];
			private _act = _t getVariable ["cti_town_occupation_activeTime", time];
			private _hold = _t getVariable ["vioc_mb_hold", -1]; //--- mision B: guarnicion presente que mantiene keyTick (sin front_line_mb no se toca)
			if (((_t getVariable ["cti_town_occupation_active_sideID", -9]) isEqualTo _sid) && {(_act isEqualType 0)} && {(time - _act) > VIOC_FL_GAR_MIN} && {(time - _act) <= _max}
				&& {(time - (_t getVariable ["VIOC_PERF_creating", -1000])) > 180} && {!(_hold isEqualType 0) || {_hold <= time}}) then {
				private _c = getPosATL _t;
				private _en = [(_t nearEntities ["AllVehicles", VIOC_FL_GAR_ENEMY]) unitsBelowHeight _air, (_sid) call CTI_CO_FNC_GetSideFromID] call CTI_CO_FNC_GetAreaEnemiesCount;
				if ((_en == 0) && {(_pl findIf {(_x distance2D _c) < VIOC_FL_GAR_FREE}) < 0}) then {
					_t setVariable ["cti_town_occupation_activeTime", time - _max - 1];
					[3] call VIOC_FL_fnc_stat;
					[format ["%1 (%2, retaguardia): guarnicion activa sin enemigos a %3 m ni jugadores a %4 m: se desactiva ya", [_t] call VIOC_FL_fnc_tname,
						[_sid] call VIOC_FL_fnc_sideName, VIOC_FL_GAR_ENEMY, VIOC_FL_GAR_FREE]] call VIOC_FL_fnc_log;
				};
			};
		};
	} forEach VIOC_FL_T;
};

//--- Refuerzos de capital_reinforce que defienden una capital de retaguardia (en posicion o yendo a ella): se borran sin enemigos
//--- a VIOC_FL_GAR_ENEMY m de la capital ni jugadores a VIOC_FL_GAR_FREE m de ellos. El bucle de capital_reinforce cierra la entrada.
VIOC_FL_fnc_crTick = {
	private _cap = missionNamespace getVariable ["VIOC_CR_CAP", objNull];
	private _grs = missionNamespace getVariable ["VIOC_CR_GROUPS", []];
	if (!(_cap isEqualType objNull) || {isNull _cap} || {!(_grs isEqualType [])} || {count _grs == 0}) exitWith {};
	if !([_cap] call VIOC_FL_fnc_isRear) exitWith {};
	private _sid = _cap getVariable ["cti_town_sideID", -1];
	private _air = missionNamespace getVariable ["CTI_TOWNS_OCCUPATION_DETECTION_RANGE_AIR", 20];
	if (([(_cap nearEntities ["AllVehicles", VIOC_FL_GAR_ENEMY]) unitsBelowHeight _air, (_sid) call CTI_CO_FNC_GetSideFromID] call CTI_CO_FNC_GetAreaEnemiesCount) > 0) exitWith {};
	private _pl = call VIOC_FL_fnc_players;
	{
		private _e = _x;
		if ((_e isEqualType createHashMap) && {!(_e getOrDefault ["done", true])} && {(_e getOrDefault ["state", ""]) in ["hold", "walk"]} && {(_e getOrDefault ["sid", -9]) isEqualTo _sid}) then {
			private _g = _e getOrDefault ["g", grpNull];
			private _alive = if (isNull _g) then {[]} else {(units _g) select {alive _x}};
			private _seen = false;
			{
				private _u = _x;
				if ((_pl findIf {(_x distance2D _u) < VIOC_FL_GAR_FREE}) >= 0) exitWith {_seen = true};
			} forEach _alive;
			if (!_seen) then {
				{ deleteVehicle _x } forEach _alive;
				if (!isNull _g) then {deleteGroup _g};
				_e set ["done", true];
				[4] call VIOC_FL_fnc_stat;
				[format ["refuerzo de capital_reinforce en %1 (retaguardia) borrado: %2 hombres, sin enemigos a %3 m ni jugadores a %4 m", [_cap] call VIOC_FL_fnc_tname,
					count _alive, VIOC_FL_GAR_ENEMY, VIOC_FL_GAR_FREE]] call VIOC_FL_fnc_log;
			};
		};
	} forEach (_grs + []);
};

VIOC_FL_fnc_loop = {
	waitUntil {sleep 2; !isNil "CTI_InitTowns" && {!isNil "CTI_Init_Server"}};
	waitUntil {sleep 2; ({isNil {_x getVariable "cti_town_sideID"}} count CTI_Towns) == 0};
	VIOC_FL_ON = ["VIOC_FRONTLINE", 1, [0, 1]] call VIOC_FL_fnc_par;
	VIOC_FL_R = ["VIOC_FRONTLINE_RANGE", 2500, [2500, 3500, 5000]] call VIOC_FL_fnc_par;
	if (VIOC_FL_ON < 1) exitWith {["apagado en el lobby (VIOC_FRONTLINE = 0): la IA ataca cualquier pueblo, como antes"] call VIOC_FL_fnc_log};
	sleep 5;
	call VIOC_FL_fnc_prep;
	VIOC_FL_ST = VIOC_FL_T apply {[false, time, -9, "", false]};
	isNil {[true, true] call VIOC_FL_fnc_classify};
	VIOC_FL_T0 = time;
	VIOC_FL_ACTIVE = true;
	publicVariable "VIOC_FL_ACTIVE";
	private _nr = {_x select 0} count VIOC_FL_ST;
	private _nf = {!(_x select 0) && {(_x select 2) in [CTI_WEST_ID, CTI_EAST_ID]}} count VIOC_FL_ST;
	[format ["lista: %1 pueblos de frente y %2 de retaguardia (Oeste y Este); recalculo cada %3 s, histeresis %4 s", _nf, _nr, VIOC_FL_PERIOD, VIOC_FL_HYST]] call VIOC_FL_fnc_log;
	private _sig = VIOC_FL_T apply {_x getVariable ["cti_town_sideID", -1]};
	private _nextG = time + VIOC_FL_PERIOD;
	while {!(missionNamespace getVariable ["CTI_GameOver", false])} do {
		sleep VIOC_FL_POLL;
		private _s2 = VIOC_FL_T apply {_x getVariable ["cti_town_sideID", -1]};
		if (!(_s2 isEqualTo _sig) || {time >= VIOC_FL_NEXT} || {VIOC_FL_NOW}) then {
			_sig = _s2;
			VIOC_FL_NOW = false;
			isNil {[false, false] call VIOC_FL_fnc_classify};
		};
		if (time >= _nextG) then {
			_nextG = time + VIOC_FL_PERIOD;
			call VIOC_FL_fnc_garTick;
			isNil {call VIOC_FL_fnc_crTick};
		};
	};
};

//--- ---------------------------------- consola ----------------------------------
//--- [posicion u objeto] -> pueblo mas cercano (por defecto, al jugador)
VIOC_FL_fnc_nearTown = {
	params [["_p", objNull]];
	if (_p isEqualType objNull) then {_p = if (isNull _p) then {if (isNull player) then {[0, 0, 0]} else {getPosATL player}} else {getPosATL _p}};
	private _best = objNull;
	private _bd = 1e9;
	{ private _d = _x distance2D _p; if (_d < _bd) then {_bd = _d; _best = _x} } forEach (missionNamespace getVariable ["CTI_Towns", []]);
	_best
};

VIOC_FL_fnc_info = {
	if (VIOC_FL_ON < 1) exitWith {"VIOC front_line: apagado en el lobby (VIOC_FRONTLINE = 0) o todavia arrancando"};
	if !(missionNamespace getVariable ["VIOC_FL_ACTIVE", false]) exitWith {"VIOC front_line: todavia calculando (arranca unos segundos despues de que los pueblos tienen duenio)"};
	private _nl = toString [10];
	private _lines = [format ["VIOC front_line: distancia de frente %1 m, histeresis %2 s, recalculo cada %3 s (proximo en %4 s). Puentes: %5. Pares sin paso por tierra: %6.",
		VIOC_FL_R, VIOC_FL_HYST, VIOC_FL_PERIOD, round ((VIOC_FL_NEXT - time) max 0), count VIOC_FL_BRIDGES, count VIOC_FL_CUT]];
	_lines pushBack format ["Cuentas %1 = [recalculos, a retaguardia, a frente, guarniciones retiradas, refuerzos borrados, regla de seguridad]", VIOC_FL_INFO];
	_lines pushBack format ["Uniones de componentes: %1. Aislados (siempre frente): %2.", VIOC_FL_JOINS apply {format ["%1-%2 %3 m (%4)", [VIOC_FL_T select (_x select 0)] call VIOC_FL_fnc_tname,
		[VIOC_FL_T select (_x select 1)] call VIOC_FL_fnc_tname, round (_x select 2), _x select 3]}, call VIOC_FL_fnc_isoNames];
	{
		private _sid = _x;
		private _fr = [];
		private _rr = [];
		{
			_x params ["_rear", "_last", "_s", "_why", "_c"];
			if (_s == _sid) then {
				private _nm = [VIOC_FL_T select _forEachIndex] call VIOC_FL_fnc_tname;
				if (_rear) then {_rr pushBack _nm} else {
					_fr pushBack (if (_c) then {format ["%1 [%2]", _nm, _why]} else {format ["%1 [sin condicion de frente: pasa a retaguardia en ~%2 s]", _nm, round ((VIOC_FL_HYST - (time - _last)) max 0)]});
				};
			};
		} forEach VIOC_FL_ST;
		_lines pushBack format ["%1 - FRENTE (%2): %3", [_sid] call VIOC_FL_fnc_sideName, count _fr, _fr joinString "; "];
		_lines pushBack format ["%1 - RETAGUARDIA (%2): %3", [_sid] call VIOC_FL_fnc_sideName, count _rr, _rr joinString ", "];
	} forEach [CTI_WEST_ID, CTI_EAST_ID];
	private _g = {(_x select 2) == CTI_RESISTANCE_ID} count VIOC_FL_ST;
	_lines pushBack format ["Guerrilla: %1 pueblos (no se clasifican: siempre se pueden atacar).", _g];
	if (count VIOC_FL_FORCE > 0) then {_lines pushBack format ["Forzados desde la consola: %1", (keys VIOC_FL_FORCE) apply {format ["%1 = %2", [VIOC_FL_T select _x] call VIOC_FL_fnc_tname, VIOC_FL_FORCE getOrDefault [_x, ""]]}]};
	private _t = _lines joinString _nl;
	if (hasInterface) then {copyToClipboard _t};
	_t
};

//--- [pueblo] (por defecto el mas cercano a ti) -> por que es frente o retaguardia: vecinos a la distancia de frente, agua, puentes, bases
VIOC_FL_fnc_why = {
	params [["_t", objNull]];
	if (isNull _t) then {_t = call VIOC_FL_fnc_nearTown};
	if (isNull _t) exitWith {"VIOC front_line: no hay pueblos"};
	private _i = VIOC_FL_T find _t;
	if (_i < 0 || {count VIOC_FL_ST <= _i}) exitWith {"VIOC front_line: todavia calculando"};
	private _nl = toString [10];
	(VIOC_FL_ST select _i) params ["_rear", "_last", "_s", "_why", "_c"];
	private _lines = [format ["%1 (duenio %2): %3%4", [_t] call VIOC_FL_fnc_tname, [_t getVariable ["cti_town_sideID", -1]] call VIOC_FL_fnc_sideName,
		["FRENTE", "RETAGUARDIA"] select _rear, if (_c) then {format [" - %1", _why]} else {""}]];
	if (!_rear && {!_c} && {_s in [CTI_WEST_ID, CTI_EAST_ID]}) then {_lines pushBack format ["Sin condicion de frente desde hace %1 s: pasa a retaguardia a los %2 s.", round (time - _last), VIOC_FL_HYST]};
	if (_rear) then {_lines pushBack "Retaguardia: sin pueblos de otro duenio por tierra ni bases enemigas a la distancia de frente."};
	_lines pushBack format ["Vecinos por tierra a menos de %1 m:", VIOC_FL_R];
	{
		_x params ["_j", "_d", "_via"];
		private _o = (VIOC_FL_T select _j) getVariable ["cti_town_sideID", -1];
		_lines pushBack format ["  %1 (%2) %3 m%4%5", [VIOC_FL_T select _j] call VIOC_FL_fnc_tname, [_o] call VIOC_FL_fnc_sideName, round _d,
			["", format [", por un puente (camino de %1 m)", round _via]] select (_via > 0), ["", "  <- otro duenio"] select (_o != _s)];
	} forEach (VIOC_FL_LINKS select _i);
	{
		_x params ["_a", "_b", "_d", "_w"];
		if (_a == _i || {_b == _i}) then {
			private _j = [_a, _b] select (_a == _i);
			_lines pushBack format ["  SIN PASO: %1 a %2 m (%3 m de agua seguida en linea recta y ningun puente sirve)", [VIOC_FL_T select _j] call VIOC_FL_fnc_tname, round _d, round _w];
		};
	} forEach VIOC_FL_CUT;
	{
		_x params ["_a", "_b", "_d", "_k"];
		if (_a == _i || {_b == _i}) then {_lines pushBack format ["  UNION de componentes con %1 a %2 m (%3)", [VIOC_FL_T select ([_a, _b] select (_a == _i))] call VIOC_FL_fnc_tname, round _d, _k]};
	} forEach VIOC_FL_JOINS;
	if (VIOC_FL_ISO param [_i, false]) then {_lines pushBack "Aislado: su isla no tiene paso por tierra ni puente a los demas pueblos (siempre frente)."};
	private _p = VIOC_FL_POS select _i;
	{
		private _side = _x;
		private _as = [_side] call VIOC_FL_fnc_assets;
		private _near = _as select {((_x select 0) distance2D _p) <= VIOC_FL_R};
		if (count _near > 0) then {_lines pushBack format ["Base de %1 a la distancia de frente: %2", _side, _near apply {format ["%1 a %2 m", _x select 1, round ((_x select 0) distance2D _p)]}]};
	} forEach [west, east];
	if ((VIOC_FL_FORCE getOrDefault [_i, ""]) != "") then {_lines pushBack format ["Forzado desde la consola: %1", VIOC_FL_FORCE getOrDefault [_i, ""]]};
	_lines joinString _nl
};

//--- -> objetivo de cada escuadra IA de BECTI (cti_order_pos) y si alguno es un pueblo enemigo de retaguardia (no deberia haber)
VIOC_FL_fnc_targets = {
	private _nl = toString [10];
	private _lines = [];
	private _bad = 0;
	{
		private _side = _x;
		private _sid = (_side) call CTI_CO_FNC_GetSideID;
		{
			private _g = _x;
			private _p = _g getVariable ["cti_order_pos", objNull];
			if ((_p isEqualType objNull) && {!isNull _p} && {_p in CTI_Towns}) then {
				private _r = ([_p] call VIOC_FL_fnc_isRear) && {(_p getVariable ["cti_town_sideID", -1]) != _sid};
				if (_r) then {_bad = _bad + 1};
				_lines pushBack format ["%1 %2%3 -> %4 (%5)%6", _side, groupId _g, ["", " (jugador)"] select (isPlayer (leader _g)), [_p] call VIOC_FL_fnc_tname,
					[_p getVariable ["cti_town_sideID", -1]] call VIOC_FL_fnc_sideName, ["", "  <- RETAGUARDIA ENEMIGA"] select _r];
			};
		} forEach ((_side) call CTI_CO_FNC_GetSideGroups);
	} forEach [west, east];
	private _t = (format ["VIOC front_line: objetivos de las escuadras (%1 en un pueblo enemigo de retaguardia)", _bad]) + _nl + (_lines joinString _nl);
	if (hasInterface) then {copyToClipboard _t};
	_t
};

//--- [sin histeresis] -> recalcula ya y devuelve el estado
VIOC_FL_fnc_recalc = {
	params [["_hard", false]];
	if !(missionNamespace getVariable ["VIOC_FL_ACTIVE", false]) exitWith {"VIOC front_line: apagado o todavia calculando"};
	isNil {[_hard, false] call VIOC_FL_fnc_classify};
	call VIOC_FL_fnc_info
};

//--- [pueblo, "rear" / "front" / ""] -> fuerza (o quita el forzado de) un pueblo y recalcula sin histeresis para el
VIOC_FL_fnc_force = {
	params [["_t", objNull], ["_mode", ""]];
	if !(missionNamespace getVariable ["VIOC_FL_ACTIVE", false]) exitWith {"VIOC front_line: apagado o todavia calculando"};
	private _i = VIOC_FL_T find _t;
	if (_i < 0) exitWith {"VIOC front_line: no es un pueblo en juego"};
	if (_mode in ["rear", "front"]) then {VIOC_FL_FORCE set [_i, _mode]} else {VIOC_FL_FORCE deleteAt _i};
	isNil {[false, false] call VIOC_FL_fnc_classify};
	[_t] call VIOC_FL_fnc_why
};

//--- Marcadores locales de depuracion (anfitrion): todos los pueblos con duenio, verde = frente, gris = retaguardia (otra vez: borrar)
VIOC_FL_fnc_markers = {
	if (!hasInterface) exitWith {};
	if (isNil "VIOC_FL_DBGMK") then {VIOC_FL_DBGMK = []};
	if (count VIOC_FL_DBGMK > 0) exitWith {
		{ deleteMarkerLocal _x } forEach VIOC_FL_DBGMK;
		VIOC_FL_DBGMK = [];
	};
	{
		_x params ["_rear", "", "_s"];
		if (_s in [CTI_WEST_ID, CTI_EAST_ID]) then {
			private _p = VIOC_FL_POS select _forEachIndex;
			private _m = createMarkerLocal [format ["VIOC_FL_dbg%1", _forEachIndex], _p];
			_m setMarkerTypeLocal "mil_dot";
			_m setMarkerColorLocal (["ColorGreen", "ColorGrey"] select _rear);
			_m setMarkerTextLocal format ["%1 %2 (%3)", ["FRENTE", "RETAG."] select _rear, [VIOC_FL_T select _forEachIndex] call VIOC_FL_fnc_tname, [_s] call VIOC_FL_fnc_sideName];
			VIOC_FL_DBGMK pushBack _m;
		};
	} forEach VIOC_FL_ST;
};

[] spawn VIOC_FL_fnc_loop;

